// ---- Judge bias lab (t-bias), part a: shared helpers, the one-pair animation, the padding toggle ----
// Data: window.JB_DATA (31_js_bias_data.js, generated by src/bias/mk_data.py). Everything initialises on the
// first render of the tab, so file order does not matter.
window.JB=(function(){
  const RM=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
  const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const stat=(k,v,d)=>'<div class="stat"><div class="k">'+k+'</div><div class="v">'+v+'</div><div class="d">'+(d||'')+'</div></div>';
  const NAME={'gpt-4-1106-preview':'GPT-4 Turbo (1106)','claude-3-opus-20240229':'Claude 3 Opus','claude-3-5-sonnet-20240620':'Claude 3.5 Sonnet (June)',
    'gemini-1.5-pro-api-0514':'Gemini 1.5 Pro (May)','llama-3-70b-instruct':'Llama 3 70B Instruct','gpt-4-0314':'GPT-4 (0314)',
    'gpt-4-0613':'GPT-4 (0613)','gpt-4-turbo-2024-04-09':'GPT-4 Turbo (Apr)','gpt-3.5-turbo-0613':'GPT-3.5 Turbo (0613)','claude-2.1':'Claude 2.1',
    'claude-3-sonnet-20240229':'Claude 3 Sonnet','mistral-large-2402':'Mistral Large (2402)','mistral-medium':'Mistral Medium',
    'gpt-4':'GPT-4','claude-v1':'Claude-v1','gpt-3.5-turbo':'GPT-3.5-turbo','vicuna-13b-v1.2':'Vicuna-13B','alpaca-13b':'Alpaca-13B','llama-13b':'LLaMA-13B'};
  const nm=k=>NAME[k]||k;
  const link=(s,extra)=>'<a href="'+s.url+'" target="_blank" rel="noopener noreferrer">'+esc(s.cite)+'</a>, '+esc(s.ver)+(extra?', '+esc(extra):'');
  const onRender=f=>{(window.TAB_RENDER=window.TAB_RENDER||{});(window.TAB_RENDER['t-bias']=window.TAB_RENDER['t-bias']||[]).push(f)};
  return {RM,esc,stat,nm,link,onRender};
})();

(function(){
  const {RM,esc,stat,nm,link,onRender}=JB;
  let done=false;
  onRender(function(){ if(done)return; done=true; initAnim(); initPad(); });

  // raw verdict label to a value from the candidate's side (+ favours Claude 3 Opus), given which answer sat in position A
  const RAW={'A>>B':2,'A>B':1,'A=B':0,'B>A':-1,'B>>A':-2};
  const candSide=(lab,candFirst)=>candFirst?RAW[lab]:-RAW[lab];
  const vchip=v=>v>0?'<span class="vd c">Claude'+(v>1?' &#8811;':'')+'</span>':v<0?'<span class="vd b">baseline'+(v<-1?' &#8811;':'')+'</span>':'<span class="vd t">tie</span>';

  function initAnim(){
    const D=JB_DATA.dice,G=D.gold,J={};D.judges.forEach(j=>J[j.id]=j);
    const el=id=>document.getElementById(id);
    const ciB='316.5 to 383.5',ciC='346.65 to 353.35';
    el('jb-prompt').innerHTML='<b>The prompt</b> (Arena-Hard-Auto v0.1, cluster &ldquo;Dice Probability Calculations&rdquo;): &ldquo;'+esc(D.prompt)+'&rdquo; The baseline answer is GPT-4 (0314)&rsquo;s; the candidate is Claude 3 Opus&rsquo;s. Both are shown in full under &ldquo;full answer&rdquo;.';
    const card=(k)=>{const b=k==='base';return '<div class="jb-ans '+(b?'base':'cand')+'" id="jb-'+k+'"><span class="pos" id="jb-'+k+'-pos"></span><span class="who">'+(b?'GPT-4 (0314), the baseline':'Claude 3 Opus, the candidate')+'</span>'+
      '<span class="ci">'+(b?ciB:ciC)+'</span><span class="'+(b?'ok':'no')+'">'+(b?'Right':'Wrong: divides by &radic;100 twice')+'</span>'+
      '<details><summary>full answer</summary><pre>'+esc(b?D.a_base:D.a_cand)+'</pre></details></div>'};
    el('jb-pair').innerHTML=card('base')+card('cand');
    const ticks=[['-2','baseline &#8811;'],['-1','baseline &gt;'],['0','tie'],['1','Claude &gt;'],['2','Claude &#8811;']];
    el('jb-meter').innerHTML='<div class="ax"></div>'+ticks.map((t,i)=>'<span class="tk" style="left:'+(i*25)+'%;'+(i===0?'transform:none':i===4?'transform:translateX(-100%)':'')+'">'+t[1]+'</span>').join('')+'<div class="mk" id="jb-mk" style="left:50%;opacity:0"></div>';
    el('jb-meter').insertAdjacentHTML('afterend','<p class="small mute" style="margin:0">Verdict scale: &gt; better, &#8811; much better (Arena-Hard&rsquo;s five labels), drawn from the candidate&rsquo;s side whatever the order.</p>');
    el('jb-src').innerHTML='Verdicts and quotes: '+link({cite:'Arena-Hard-Auto v0.1 released judgments',url:'https://huggingface.co/datasets/lmarena-ai/arena-hard-auto',ver:'judged in 2024, files read 4 Oct 2026'},'prompt uid '+D.uid)+'. Order 1 is the released &ldquo;game 1&rdquo; (baseline in position A), order 2 is &ldquo;game 2&rdquo; (swapped). Gold line: the exact distribution of the sum of 100 dice, computed in <code>src/bias/mk_data.py</code>.';
    const QL=(id,g)=>'<span class="jn">'+nm(id)+', order '+(g+1)+'</span> wrote <code>[['+J[id].scores[g]+']]</code>: &ldquo;'+esc(J[id].quotes[g])+'&rdquo;';
    const order=['gpt-4-1106-preview','claude-3-opus-20240229','claude-3-5-sonnet-20240620','gemini-1.5-pro-api-0514','llama-3-70b-instruct'];
    const fam={'gpt-4-1106-preview':'OpenAI','claude-3-opus-20240229':'Anthropic','claude-3-5-sonnet-20240620':'Anthropic','gemini-1.5-pro-api-0514':'Google','llama-3-70b-instruct':'Meta'};
    const v=(id,g)=>candSide(J[id].scores[g],g===1);
    // steps: [candFirst, verdicts read so far as [judge, game] list, meter value or null, quote html, extra mode, caption]
    const S=[
      {cf:false,read:[],m:null,q:'',x:'gold',c:'The question has one right answer. The exact distribution of the sum of 100 fair dice puts '+G.cover+'% of outcomes between '+G.lo+' and '+G.hi+'. GPT-4 (0314) is right. Claude 3 Opus divided the standard deviation of the sum by &radic;100 a second time; its interval holds only '+G.cand_cover+'% of outcomes. Press play to have judges grade the pair.'},
      {cf:false,read:[['gpt-4-1106-preview',0]],m:['gpt-4-1106-preview',0],x:'',c:'GPT-4 Turbo grades it with the baseline in position A. Arena-Hard&rsquo;s judge prompt asks the judge to answer the question first; this time its own answer made the same &radic;n slip ('+esc(J['gpt-4-1106-preview'].own[0])+'), so it called the wrong answer much better.'},
      {cf:true,read:[['gpt-4-1106-preview',0],['gpt-4-1106-preview',1]],m:['gpt-4-1106-preview',1],x:'',c:'Same judge, same two answers, positions swapped. This time its own worked answer came out right, '+esc(J['gpt-4-1106-preview'].own[1])+', and the verdict flipped to the baseline. One pair cannot separate the order from run-to-run variation; over all its released Arena-Hard judgments, GPT-4 Turbo gave the same winner in both orders in 67.4% of cases.'},
      {cf:false,read:[['gpt-4-1106-preview',0],['gpt-4-1106-preview',1],['claude-3-opus-20240229',0]],m:['claude-3-opus-20240229',0],x:'',c:'Now a judge from the candidate&rsquo;s own family: Claude 3 Opus, baseline in position A. Its own worked answer is the candidate&rsquo;s answer, slip included, and it prefers the candidate.'},
      {cf:true,read:[['gpt-4-1106-preview',0],['gpt-4-1106-preview',1],['claude-3-opus-20240229',0],['claude-3-opus-20240229',1]],m:['claude-3-opus-20240229',1],x:'',c:'Swapped, Claude 3 Opus still prefers the candidate: consistent, and wrong. One pair is an anecdote, not a rate. Over eight models judged by all five released judges, Claude 3 Opus scored Anthropic models 4.5 points above the other judges&rsquo; mean and other models 1.5 above; GPT-4 Turbo scored OpenAI models 1.7 above and the rest 6.1 below (section 3, Own family).'},
      {cf:null,read:order.flatMap(id=>[[id,0],[id,1]]),m:null,x:'all',c:'Before any fix: all ten released verdicts, five judges in both orders. Read one verdict at random and the wrong answer wins half the time. Gemini 1.5 Pro and Llama 3 70B each picked whichever answer came first; only Claude 3.5 Sonnet picked the right answer in both orders.'},
      {cf:null,read:order.flatMap(id=>[[id,0],[id,1]]),m:null,x:'swap',c:'After fix 1, swap and require agreement (Zheng et al.&rsquo;s conservative rule): a judge that disagrees with itself across the two orders scores a tie. Three confident verdicts become honest ties that flag the item. What survives is Claude 3.5 Sonnet for the right answer and Claude 3 Opus for its own family&rsquo;s wrong one.'},
      {cf:null,read:order.flatMap(id=>[[id,0],[id,1]]),m:null,x:'jury',c:'After fix 2, a jury. Summing the five swap-checked verdicts gives one for each answer and three ties: no winner. Dropping the two Anthropic judges (the candidate&rsquo;s family) leaves three ties. Neither fix can make a judge right on a sum it cannot do; the gold line (an exact computation, or a verified reference answer given to the judge) settles it.'}
    ];
    const pB=el('jb-base'),pC=el('jb-cand');
    function place(cf){
      // order 1: baseline left (A). order 2: candidate left (A). Narrow screens stack the cards, so swap vertically.
      const narrow=el('jb-pair').clientWidth<520;
      const dx=pB.offsetWidth+8, dy=Math.max(pB.offsetHeight,pC.offsetHeight)+8;
      if(cf===true){pB.style.transform=narrow?'translateY('+(pC.offsetHeight+8)+'px)':'translateX('+dx+'px)';pC.style.transform=narrow?'translateY(-'+(pB.offsetHeight+8)+'px)':'translateX(-'+dx+'px)'}
      else{pB.style.transform='';pC.style.transform=''}
      el('jb-base-pos').textContent=cf===null?'both orders':cf?'position B':'position A';
      el('jb-cand-pos').textContent=cf===null?'both orders':cf?'position A':'position B';
    }
    function counters(read){
      let b=0,c=0,t=0;read.forEach(([id,g])=>{const x=v(id,g);if(x>0)c++;else if(x<0)b++;else t++});
      return stat('Verdicts read',read.length,'of 10 released')+stat('For GPT-4 (0314)',b,'the right answer')+stat('For Claude 3 Opus',c,'the wrong answer')+stat('Ties',t,'');
    }
    function extra(x){
      if(x==='gold')return '<div class="co key"><div class="t">Gold line</div>Exact: P('+G.lo+' &le; sum &le; '+G.hi+') = '+G.cover+'%. Normal approximation: 350 &plusmn; 1.96 &times; &radic;(100 &times; 35/12) = 350 &plusmn; 33.47. Claude 3 Opus&rsquo;s interval 347 to 353 holds '+G.cand_cover+'%.</div>';
      if(!x)return '';
      let rows='',sb=0,sc=0,st=0,xb=0,xc=0,xt=0;
      order.forEach(id=>{const a=v(id,0),b=v(id,1);const comb=Math.sign(a)===Math.sign(b)?Math.sign(a):0;
        if(comb>0)sc++;else if(comb<0)sb++;else st++;
        if(fam[id]!=='Anthropic'){if(comb>0)xc++;else if(comb<0)xb++;else xt++}
        rows+='<tr><td>'+nm(id)+' <span class="mute small">'+fam[id]+'</span></td><td>'+vchip(a)+'</td><td>'+vchip(b)+'</td>'+(x==='all'?'':'<td>'+vchip(comb)+'</td>')+'</tr>'});
      let h='<div class="tw"><table class="jb-tbl"><thead><tr><th>Judge</th><th>Order 1<br><span class="small">baseline first</span></th><th>Order 2<br><span class="small">candidate first</span></th>'+(x==='all'?'':'<th>Swap-checked</th>')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';
      if(x==='jury')h+='<div class="out">'+stat('Jury of five',sb+' : '+sc+' : '+st,'baseline : Claude : tie')+stat('Without Anthropic judges',xb+' : '+xc+' : '+xt,'baseline : Claude : tie')+stat('Gold line','GPT-4 (0314)','exact computation')+'</div>';
      return h;
    }
    let st={i:0,play:false,timer:0,vis:false,started:false,spd:1};
    function draw(i){
      const s=S[i];place(s.cf);
      const mk=el('jb-mk');
      if(s.m){mk.style.opacity=1;mk.style.left=(50+25*v(s.m[0],s.m[1]))+'%';el('jb-quote').innerHTML=QL(s.m[0],s.m[1])}
      else{mk.style.opacity=0;el('jb-quote').innerHTML=i===0?'<span class="mute">No verdict yet.</span>':'<span class="mute">All verdicts are in the table below.</span>'}
      el('jb-cnt').innerHTML=counters(s.read);el('jb-extra').innerHTML=extra(s.x);
      el('jb-cap').innerHTML='<b>Step '+(i+1)+' of '+S.length+'.</b> '+s.c;
      el('jb-s').value=i;
    }
    const ctl=el('jb-ctl');
    ctl.innerHTML='<button id="jb-b" aria-label="Previous step">&#9664;&#9664;</button><button id="jb-p" aria-label="Play">&#9654; Play</button><button id="jb-f" aria-label="Next step">&#9654;&#9654;</button>'+
      '<input type="range" id="jb-s" min="0" max="'+(S.length-1)+'" step="1" value="0" aria-label="Step"><label class="small">Speed <select id="jb-v"><option value="0.5">0.5&times;</option><option value="1" selected>1&times;</option><option value="2">2&times;</option></select></label>';
    const box=el('jb-anim');
    const live=()=>st.vis&&!document.hidden&&box.offsetParent!==null;
    function tick(){st.timer=0;if(!st.play||!live())return;if(st.i>=S.length-1){setPlay(false);return}st.i++;draw(st.i);if(st.i>=S.length-1){setPlay(false);return}st.timer=setTimeout(tick,4200/st.spd)}
    function kick(){if(st.play&&live()&&!st.timer)st.timer=setTimeout(tick,4200/st.spd);else if(!live()&&st.timer){clearTimeout(st.timer);st.timer=0}}
    function setPlay(p){st.play=p;el('jb-p').innerHTML=p?'&#10073;&#10073; Pause':'&#9654; Play';el('jb-p').setAttribute('aria-label',p?'Pause':'Play');
      if(!p&&st.timer){clearTimeout(st.timer);st.timer=0}if(p&&st.i>=S.length-1){st.i=0;draw(0)}kick()}
    el('jb-p').addEventListener('click',()=>setPlay(!st.play));
    el('jb-f').addEventListener('click',()=>{setPlay(false);st.i=Math.min(S.length-1,st.i+1);draw(st.i)});
    el('jb-b').addEventListener('click',()=>{setPlay(false);st.i=Math.max(0,st.i-1);draw(st.i)});
    el('jb-s').addEventListener('input',e=>{setPlay(false);st.i=+e.target.value;draw(st.i)});
    el('jb-v').addEventListener('change',e=>{st.spd=+e.target.value});
    if('IntersectionObserver' in window){new IntersectionObserver(es=>{st.vis=es[es.length-1].isIntersecting;
      if(st.vis&&!st.started&&box.offsetParent){st.started=true;if(!RM)setPlay(true)}kick()},{threshold:.2}).observe(box)}else st.vis=true;
    document.addEventListener('visibilitychange',kick);
    addEventListener('resize',()=>{if(box.offsetParent)place(S[st.i].cf)});
    onRender(()=>{draw(st.i);kick()});
    draw(0);
  }

  function initPad(){
    const O=JB_DATA.ocean,L=JB_DATA.length.alpaca;
    const el=id=>document.getElementById(id);
    let mode='concise';
    const pct=p=>(100*p).toFixed(p<0.01||p>0.99?4:1)+'%';const prevW={};
    function draw(){
      const c=O[mode],maxc=Math.max(O.verbose.output.length,O.baseline_output.length,O.concise.output.length);
      const row=(label,val,max,col,txt)=>{const w=(100*val/max).toFixed(1);const o=prevW[label]!=null?prevW[label]:w;prevW[label]=w;return '<div class="jb-len"><span>'+label+'</span><span class="tr"><i data-w="'+w+'" style="width:'+o+'%;background:'+col+'"></i></span><span style="text-align:right">'+txt+'</span></div>'};
      const a=L[mode];
      el('jb-padbody').innerHTML=
        '<p class="small"><b>Instruction:</b> &ldquo;'+esc(O.instruction)+'&rdquo; Judge: GPT-4 Turbo (1106) as AlpacaEval 2&rsquo;s annotator, comparing against the same model&rsquo;s default answer. Both versions name the Pacific; the verbose one adds facts the question did not ask for.</p>'+
        '<div class="jb-pair"><div class="jb-ans base"><span class="pos">baseline, default prompt</span><span class="who">GPT-4 Turbo, default</span><pre style="max-height:150px">'+esc(O.baseline_output)+'</pre></div>'+
        '<div class="jb-ans cand"><span class="pos">candidate</span><span class="who">GPT-4 Turbo, asked to be '+mode+'</span><pre style="max-height:150px">'+esc(c.output)+'</pre></div></div>'+
        row('Baseline length',O.baseline_output.length,maxc,'var(--c1)',O.baseline_output.length+' ch')+
        row('Candidate length',c.output.length,maxc,'var(--c2)',c.output.length+' ch')+
        row('Judge prefers candidate',c.p_win,1,'var(--c4)',pct(c.p_win))+
        '<p class="small" style="margin-top:12px"><b>Over all 805 instructions</b> (same model, same judge, same baseline):</p>'+
        row('Raw win rate',a.raw,100,'var(--c2)',a.raw.toFixed(1)+'%')+
        row('Length-controlled',a.lc,100,'var(--c3)',a.lc.toFixed(1)+'%')+
        row('Mean length',a.chars,2600,'var(--dim)',a.chars+' ch')+
        '<p class="small">Asking for more words moves the raw win rate from '+L.concise.raw.toFixed(1)+'% to '+L.verbose.raw.toFixed(1)+'%, a gap of '+(L.verbose.raw-L.concise.raw).toFixed(1)+' points; on '+L.flips+' of the '+L.n+' instructions the verbose version wins where the concise one loses. The length-controlled win rate (a regression that predicts the verdict with the length difference held at zero) shrinks the gap to '+(L.verbose.lc-L.concise.lc).toFixed(1)+' points. Mean baseline length: '+L.baseline_chars+' characters.</p>';
      requestAnimationFrame(()=>requestAnimationFrame(()=>document.querySelectorAll('#jb-padbody i[data-w]').forEach(i=>{i.style.width=i.dataset.w+'%'})));
    }
    el('jb-pc').addEventListener('click',()=>{mode='concise';el('jb-pc').classList.add('on');el('jb-pv').classList.remove('on');draw()});
    el('jb-pv').addEventListener('click',()=>{mode='verbose';el('jb-pv').classList.add('on');el('jb-pc').classList.remove('on');draw()});
    el('jb-padsrc').innerHTML='Answers, verdict probabilities and raw win rates: the released annotations in '+link(JB_DATA.length.alpaca.src,'results/gpt4_1106_preview_{concise,verbose}, annotator weighted_alpaca_eval_gpt4_turbo')+'; raw win rates recounted from them (64.30 and 22.92, matching the leaderboard file). Length-controlled rates: the AlpacaEval 2 leaderboard file. Method: '+link(JB_DATA.length.alpaca.paper)+'.';
    draw();
  }
})();
